def intensity(M, N, K, bytes_per=2):
    flops = 2 * M * N * K
    moved = bytes_per * (M * K + K * N + M * N)
    return flops / moved


def attainable(i, peak=989e12, bw=3.35e12):
    return min(peak, bw * i)


for shape in [(4096, 4096, 4096), (1, 4096, 4096)]:
    i = intensity(*shape)
    print(shape, round(i, 1), 'FLOP/B ->', round(attainable(i) / 1e12, 1), 'TFLOP/s')
